from ortools.sat.python import cp_model

def print_board(board, rows, cols):
    result = "\\begin{array}{"
    for _ in range(cols):
        result += "c"
    result += "}\n"

    for r in range(rows):
        for c in range(cols):
            if board[r][c].solution_value() == 1:
                result += "b "
            else:
                result += "w "
            if c < cols - 1:
                result += "& "
        if r < rows - 1:
            result += "\\\\\n"
    result += "\\end{array}"
    return result

# Define the dimensions of the board
rows, cols = 5, 44
num_black_cells = 3 * cols + 2

# Initialize the model
model = cp_model.CpModel()

# Create variables for the board
board = [[model.NewIntVar(0, 1, f"cell_{r}_{c}") for c in range(cols)] for r in range(rows)]

# Add constraint for the total number of black cells
model.Add(sum(board[r][c] for r in range(rows) for c in range(cols)) == num_black_cells)

# Add constraints for adjacency
for r in range(rows):
    for c in range(cols):
        adjacents = []
        if r > 0: adjacents.append(board[r-1][c])
        if r < rows-1: adjacents.append(board[r+1][c])
        if c > 0: adjacents.append(board[r][c-1])
        if c < cols-1: adjacents.append(board[r][c+1])
        model.Add(sum(adjacents) <= 2 * board[r][c])

# Solve the model
solver = cp_model.CpSolver()
status = solver.Solve(model)
if status in [cp_model.OPTIMAL, cp_model.FEASIBLE]:
    print(print_board(board, rows, cols))
else:
    print("No solution found")
